const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let input = [];
rl.on('line', (line) => {
    input.push(line);
});

rl.on('close', () => {
    const [n, m] = input[0].split(' ').map(Number);
    const a = input[1].split(' ').map(Number);

    // Split the array into two halves
    const mid = Math.floor(n / 2);
    const left = a.slice(0, mid);
    const right = a.slice(mid);

    // Generate all possible subset sums modulo m for the left half
    const leftSums = new Set();
    leftSums.add(0);
    for (const num of left) {
        const newSums = new Set();
        for (const sum of leftSums) {
            newSums.add((sum + num) % m);
        }
        for (const sum of newSums) {
            leftSums.add(sum);
        }
    }

    // Generate all possible subset sums modulo m for the right half
    const rightSums = new Set();
    rightSums.add(0);
    for (const num of right) {
        const newSums = new Set();
        for (const sum of rightSums) {
            newSums.add((sum + num) % m);
        }
        for (const sum of newSums) {
            rightSums.add(sum);
        }
    }

    // Convert to sorted arrays
    const leftArr = Array.from(leftSums).sort((a, b) => a - b);
    const rightArr = Array.from(rightSums).sort((a, b) => a - b);

    let max = 0;

    // For each sum in the right half, find the best matching sum in the left half
    for (const r of rightArr) {
        // We want to find l in leftArr such that (l + r) % m is maximized
        // This is equivalent to finding l such that l <= (m - 1 - r)
        // If no such l exists, then we take the maximum l and compute (l + r) % m
        const target = m - 1 - r;
        let low = 0;
        let high = leftArr.length - 1;
        let best = -1;
        while (low <= high) {
            const mid = Math.floor((low + high) / 2);
            if (leftArr[mid] <= target) {
                best = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        if (best !== -1) {
            const candidate = (leftArr[best] + r) % m;
            if (candidate > max) {
                max = candidate;
            }
        }
        // Also check the maximum element in leftArr
        const candidate = (leftArr[leftArr.length - 1] + r) % m;
        if (candidate > max) {
            max = candidate;
        }
    }

    console.log(max);
});
